'use client';

import { PolymarketMarket } from '@/types/polymarket';

interface MarketCardProps {
  market: PolymarketMarket;
}

export default function MarketCard({ market }: MarketCardProps) {
  const formatPrice = (price: string | undefined) => {
    if (!price) return 'N/A';
    const numPrice = parseFloat(price);
    return (numPrice * 100).toFixed(2) + '%';
  };

  const formatVolume = (volume: string | undefined) => {
    if (!volume) return 'N/A';
    const numVolume = parseFloat(volume);
    if (numVolume >= 1000000) {
      return '$' + (numVolume / 1000000).toFixed(2) + 'M';
    }
    if (numVolume >= 1000) {
      return '$' + (numVolume / 1000).toFixed(2) + 'K';
    }
    return '$' + numVolume.toFixed(2);
  };

  const getStatusBadge = () => {
    if (market.closed) {
      return <span className="px-3 py-1 rounded-full text-xs font-semibold bg-zinc-500 text-white">Closed</span>;
    }
    if (market.archived) {
      return <span className="px-3 py-1 rounded-full text-xs font-semibold bg-zinc-400 text-white">Archived</span>;
    }
    if (market.active) {
      return <span className="px-3 py-1 rounded-full text-xs font-semibold bg-green-500 text-white">Active</span>;
    }
    return <span className="px-3 py-1 rounded-full text-xs font-semibold bg-yellow-500 text-white">Pending</span>;
  };

  const getOutcomes = () => {
    let outcomes: string[] = [];
    if (Array.isArray(market.outcomes)) {
      outcomes = market.outcomes;
    } else if (market.outcomes) {
      outcomes = [market.outcomes.toString()];
    }
    
    if (outcomes.length === 0 && market.tokens) {
      if (Array.isArray(market.tokens)) {
        outcomes = market.tokens
          .map((token: any) => token.outcome || token.name)
          .filter((outcome: any) => outcome);
      } else if (typeof market.tokens === 'object') {
        outcomes = Object.keys(market.tokens);
      }
    }
    
    return outcomes;
  };

  const outcomes = getOutcomes();
  const tokens = market.tokens || {};

  return (
    <article className="group bg-white dark:bg-zinc-900 rounded-xl border border-zinc-200 dark:border-zinc-800 overflow-hidden hover:shadow-xl hover:border-zinc-300 dark:hover:border-zinc-700 transition-all duration-300 flex flex-col h-full">
      {/* Card Header */}
      <div className="p-6 pb-4">
        <div className="flex items-start justify-between gap-3 mb-3">
          <h3 className="text-lg font-bold text-zinc-900 dark:text-zinc-100 leading-tight flex-1 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
            {market.question}
          </h3>
          {getStatusBadge()}
        </div>
        
        {market.description && (
          <p className="text-sm text-zinc-600 dark:text-zinc-400 line-clamp-3 mb-4">
            {market.description}
          </p>
        )}
      </div>

      {/* Outcomes/Prices Section */}
      {outcomes.length > 0 && (
        <div className="px-6 pb-4">
          <div className="bg-zinc-50 dark:bg-zinc-800/50 rounded-lg p-4 space-y-3">
            {outcomes.slice(0, 3).map((outcome, index) => {
              const tokenKey = outcome.toLowerCase().replace(/\s+/g, '-');
              const token = tokens[tokenKey] || tokens[outcome] || {};
              const price = token.price || market.outcomePrices?.[outcome] || '0';
              const priceNum = parseFloat(price) * 100;
              
              return (
                <div key={index} className="flex items-center justify-between">
                  <span className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
                    {outcome}
                  </span>
                  <div className="flex items-center gap-2">
                    <div className="w-20 bg-zinc-200 dark:bg-zinc-700 rounded-full h-2 overflow-hidden">
                      <div 
                        className="h-full bg-blue-500 dark:bg-blue-400 transition-all"
                        style={{ width: `${priceNum}%` }}
                      />
                    </div>
                    <span className="text-sm font-bold text-zinc-900 dark:text-zinc-100 min-w-14 text-right">
                      {formatPrice(price)}
                    </span>
                  </div>
                </div>
              );
            })}
            {outcomes.length > 3 && (
              <p className="text-xs text-zinc-500 dark:text-zinc-500 pt-1">
                +{outcomes.length - 3} more outcome{outcomes.length - 3 !== 1 ? 's' : ''}
              </p>
            )}
          </div>
        </div>
      )}

      {/* Stats Footer */}
      <div className="px-6 py-4 mt-auto border-t border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900/50">
        <div className="flex items-center justify-between text-xs text-zinc-600 dark:text-zinc-400 mb-3">
          {market.volume && (
            <div className="flex items-center gap-1">
              <span className="font-medium text-zinc-700 dark:text-zinc-300">Volume:</span>
              <span className="font-semibold text-zinc-900 dark:text-zinc-100">{formatVolume(market.volume)}</span>
            </div>
          )}
          {market.liquidity && (
            <div className="flex items-center gap-1">
              <span className="font-medium text-zinc-700 dark:text-zinc-300">Liquidity:</span>
              <span className="font-semibold text-zinc-900 dark:text-zinc-100">{formatVolume(market.liquidity)}</span>
            </div>
          )}
        </div>
        
        {market.endDateISO && (
          <div className="flex items-center gap-2 text-xs text-zinc-500 dark:text-zinc-500 mb-3">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
            <span>Ends {new Date(market.endDateISO).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</span>
          </div>
        )}

        {/* Call to Action Button */}
        {market.slug && (
          <a
            href={`https://polymarket.com/event/${market.slug}`}
            target="_blank"
            rel="noopener noreferrer"
            className="block w-full mt-3 px-4 py-2.5 bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 rounded-lg font-semibold text-sm text-center hover:bg-zinc-800 dark:hover:bg-zinc-200 transition-colors group/button"
          >
            View Market
            <svg className="inline-block ml-2 w-4 h-4 group-hover/button:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </a>
        )}
      </div>
    </article>
  );
}



